from pathlib import Path
from html import escape
import json

P=Path(__file__).parent
pages={
'index.html':('Home','Tattoo studio website demo','A fictional Pittsburgh tattoo studio template with portfolio, artist matching and safe consultation preview.'),
'artists.html':('Artists','Tattoo artist portfolios','An artist selection framework with illustrative styles and no claims about real artists.'),
'gallery.html':('Gallery','Illustrative tattoo gallery','Generated tattoo concepts and studio photography for a fictional portfolio demonstration.'),
'experience.html':('Experience & Policies','Tattoo booking and studio policies','A sample consultation, design, appointment and aftercare information pathway requiring real client terms.'),
'consultation.html':('Consultation','Tattoo consultation preview','A local-only tattoo inquiry demo with no booking, upload, deposit or message delivery.'),
}
nav=[('index.html','Home'),('artists.html','Artists'),('gallery.html','Work'),('experience.html','The experience'),('consultation.html','Consultation')]
def a(path,label,cls=''):return f'<a href="/{path}" class="{cls}">{label}</a>'
def page(path,body):
 title,_,desc=pages[path]
 links=''.join(a(x,y,'active' if x==path else '') for x,y in nav)
 schema=json.dumps({'@context':'https://schema.org','@type':'WebPage','name':title+' | Vesper Ink fictional demo','description':desc,'isPartOf':{'@type':'WebSite','name':'Vesper Ink — fictional demo'}})
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Vesper Ink — Tattoo Studio Demo</title><meta name="description" content="{escape(desc,quote=True)}"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#191315"><meta property="og:type" content="website"><meta property="og:title" content="{title} | Vesper Ink — Demo"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:image" content="https://fireworks-tattoo-studio.vercel.app/assets/tattoo-hero.webp"><meta name="twitter:card" content="summary_large_image"><link rel="canonical" href="https://fireworks-tattoo-studio.vercel.app/{'' if path=='index.html' else path}"><link rel="stylesheet" href="/styles.css"><script defer src="/script.js"></script><script type="application/ld+json">{schema}</script></head><body><div class="demo">FICTIONAL FIREWORKS STUDIO DEMO · GENERATED PORTFOLIO CONCEPTS · NO APPOINTMENTS BOOKED</div><a class="skip" href="#main">Skip to content</a><header class="header wrap"><a class="brand" href="/" aria-label="Vesper Ink home"><span class="symbol">✳</span><span>VESPER <i>INK</i><small>TATTOO STUDIO · DEMO</small></span></a><button class="menu" type="button" aria-controls="nav" aria-expanded="false">Menu <span aria-hidden="true">☰</span></button><nav id="nav" aria-label="Main navigation">{links}</nav><a class="nav-cta" href="/consultation.html">Start a consultation ↗</a></header><main id="main">{body}</main><footer class="footer"><div class="wrap footgrid"><div><strong>VESPER INK</strong><p>A fictional tattoo studio website system. All art, artists, booking policies, availability and location details are examples for client customization.</p></div><div><b>Explore</b>{a('artists.html','Artists')}{a('gallery.html','Work')}{a('experience.html','The experience')}{a('consultation.html','Consultation')}</div><div><b>For a real launch</b><p>Verify artist identity, portfolio permissions, licensing, location and hours, actual booking and deposit terms, aftercare, privacy and the selected booking provider.</p></div></div><div class="wrap footline">© 2026 Vesper Ink · fictional demo <span>Forms do not submit, store, book or collect payments.</span></div></footer></body></html>'''
def intro(tag,title,copy):return f'<section class="intro wrap"><p class="eyebrow">{tag}</p><h1>{title}</h1><p>{copy}</p></section>'
def cta(title,copy):return f'<section class="cta"><div class="wrap cta-grid"><div><p class="eyebrow">YOUR IDEA, GIVEN ROOM TO GROW</p><h2>{title}</h2><p>{copy}</p></div>{a("consultation.html","Start a consultation preview ↗","button")}</div></section>'
home='''<section class="hero"><img src="/assets/tattoo-hero.webp" width="2048" height="768" alt="Generated illustrative studio photograph of an artist working on botanical tattoo artwork" fetchpriority="high"><div class="veil"></div><div class="wrap hero-copy"><p class="eyebrow">PITTSBURGH TATTOO STUDIO · FICTIONAL DEMO</p><h1>Art that<br>stays <em>with you.</em></h1><p>Bring the idea. Find the artist and approach that fit. Begin with a thoughtful consultation.</p><div class="actions"><a class="button" href="/consultation.html">Start a consultation ↗</a><a class="button outline" href="/gallery.html">Explore the work</a></div></div><span class="photo-note">Generated concept imagery · not a real artist portfolio</span></section><div class="ticker"><div class="wrap">IDEA &nbsp; ✳ &nbsp; ARTIST &nbsp; ✳ &nbsp; DESIGN &nbsp; ✳ &nbsp; APPOINTMENT &nbsp; ✳ &nbsp; AFTERCARE</div></div>'''
home+='''<section class="section wrap"><div class="section-head"><div><p class="eyebrow">A DIFFERENT KIND OF BOOKING FLOW</p><h2>Start with the art.<br>Then the details.</h2></div><p>The studio template helps visitors discover an artist, see work labeled as illustrative, understand policies and share enough about a concept for a real consultation.</p></div><div class="feature-cards"><a href="/artists.html" class="feature-card"><span>01 / THE ARTISTS</span><h3>Find your direction.</h3><p>Profiles can show real specialties, portfolios, availability and preferred project types when a client supplies them.</p><strong>Meet the artist framework ↗</strong></a><a href="/gallery.html" class="feature-card"><span>02 / THE WORK</span><h3>See the approach.</h3><p>A permission-based gallery becomes the studio's visual proof. Current images are generated examples.</p><strong>Explore gallery ↗</strong></a><a href="/experience.html" class="feature-card"><span>03 / THE PROCESS</span><h3>Know what happens next.</h3><p>Set expectations around consults, design, appointment terms and aftercare using actual policies.</p><strong>See the experience ↗</strong></a></div></section><section class="editorial"><div class="wrap editorial-grid"><img src="/assets/botanical-study.webp" width="1536" height="1024" loading="lazy" alt="Generated illustrative botanical tattoo study on an adult forearm"><div><p class="eyebrow">PERSONAL, BY DESIGN</p><h2>A piece worth<br>thinking through.</h2><p>Style, placement and scale shape a project. This sample consultation asks the practical questions and leaves real design guidance to a qualified artist.</p><a href="/consultation.html" class="text-link">Tell us about your idea ↗</a></div></div></section><section class="section wrap"><div class="section-head"><div><p class="eyebrow">FLEXIBLE FOR REAL STUDIOS</p><h2>A portfolio with<br>a purpose.</h2></div><p>Show artist-specific work, healed examples only with consent, booking policies, and a direct path from inspiration to inquiry. The client defines actual pricing and deposits.</p></div><div class="number-row"><div><span>01</span><b>Choose an artist</b></div><div><span>02</span><b>Share an idea</b></div><div><span>03</span><b>Review the details</b></div></div></section>'''+cta('An idea starts here.','This safe preview shows a consultation request. Nothing is transmitted or booked.')

artists=intro('ARTIST PROFILES / PLACEHOLDERS','The right hands for your idea.','This framework supports real artist bios, verified experience, specialties, availability and permissioned portfolios. The roles below are illustrative, not actual studio staff.')+'''<section class="wrap artist-grid"><article><span>PROFILE 01 / SAMPLE ROLE</span><h2>Fine line &amp; botanical</h2><p>Use a real artist portrait, biography, training, style preferences and portfolio with permission. The generated image below illustrates a possible direction only.</p><img src="/assets/botanical-study.webp" alt="Illustrative generated botanical tattoo concept, not artist work" loading="lazy" width="1536" height="1024"><a href="/consultation.html?artist=Fine%20line%20artist">Inquire about this style ↗</a></article><article><span>PROFILE 02 / SAMPLE ROLE</span><h2>Custom blackwork</h2><p>Show an artist's actual drawing and healed-work examples only when supplied with clear rights and context. No experience or booking claim is made here.</p><div class="placeholder"><span>ARTIST PORTFOLIO<br>IMAGE PLACEHOLDER</span></div><a href="/consultation.html?artist=Blackwork%20artist">Inquire about this style ↗</a></article></section>'''+cta('Match the idea to an artist.','Select a style and share your concept in the local-only preview.')

gallery=intro('ILLUSTRATIVE ART STUDIES','Work that speaks for itself.','The sample images below are generated for layout demonstration. Replace them with consented, attributed artist work; distinguish fresh and healed results accurately.')+'''<section class="wrap gallery-grid"><figure class="large"><img src="/assets/botanical-study.webp" alt="Generated sample botanical linework on an adult forearm" width="1536" height="1024"><figcaption>Botanical study · generated illustration, not customer work</figcaption></figure><figure><img src="/assets/tattoo-hero.webp" alt="Generated sample tattoo studio scene with an artist at work" width="2048" height="768"><figcaption>Studio process · generated scene, not a real appointment</figcaption></figure><div class="gallery-note"><span>THE REAL GALLERY</span><h2>Let real work lead.</h2><p>Client launch can filter work by artist, style and placement, with permission, captions and image optimization. A third-party gallery can be linked if the client prefers.</p></div></section>'''+cta('Have an idea in mind?','Share a general concept. Do not send private information or pay a deposit in this demo.')

experience=intro('BEFORE YOUR VISIT','A better experience begins before the appointment.','An honest studio site explains consultation, design, timing, deposit, rescheduling and aftercare terms. Every policy here is a placeholder until the client supplies current terms.')+'''<section class="wrap steps"><article><span>01</span><div><h2>Start with a concept.</h2><p>Share style, placement, approximate size and reference direction. A real studio explains whether references can be attached through an approved provider.</p></div></article><article><span>02</span><div><h2>Confirm the artist and scope.</h2><p>The studio determines fit, availability, design process, estimate and any consultation fee. The demo confirms none of these.</p></div></article><article><span>03</span><div><h2>Review booking terms.</h2><p>A real business supplies actual age/ID rules, deposit and cancellation policies, payment methods and any accessibility details before booking.</p></div></article><article><span>04</span><div><h2>Care for the work.</h2><p>Client-approved aftercare instructions and when to contact a health professional belong on the live site; this template offers no medical advice.</p></div></article></section><section class="section wrap"><p class="eyebrow">PRICING STRUCTURE / DEMO ONLY</p><h2>Clear expectations, real quotes.</h2><div class="policy-grid"><div><b>Studio minimum</b><p>Client supplies current minimum and what it includes.</p></div><div><b>Hourly or project rate</b><p>Explain the actual artist's method and estimate scope.</p></div><div><b>Deposit</b><p>Publish verified amount, refund and rescheduling terms; no deposit is accepted here.</p></div></div></section>'''+cta('Ask the right first questions.','The consultation preview routes style and project details without requesting health information.')

consult=intro('CONSULTATION / LOCAL PREVIEW','Tell us about the piece.','This fictional demo validates the idea in your browser. It does not contact an artist, upload references, book an appointment, store information or collect a deposit.')+'''<section class="wrap form-layout"><div><h2>The brief, in your words.</h2><p>A real studio can connect this form to its preferred booking provider after policies, credentials, privacy and lead delivery are verified.</p><div class="notice"><b>No booking occurs</b><p>Prices and availability require a real artist's review. Please do not enter health details or other sensitive information.</p></div></div><form id="consult" class="form"><div class="fields"><label>Name <input name="name" autocomplete="name" required maxlength="100"></label><label>Email <input name="email" type="email" autocomplete="email" required></label><label>Phone (optional) <input name="phone" type="tel" autocomplete="tel" pattern="[0-9+() .-]{7,20}"></label><label>Style <select name="style" required><option value="">Choose direction</option><option>Fine line / botanical</option><option>Blackwork</option><option>Illustrative</option><option>Not sure</option></select></label><label>Preferred artist <select name="artist" required><option value="">Choose preference</option><option>Fine line artist</option><option>Blackwork artist</option><option>Open to recommendation</option></select></label><label>Placement <input name="placement" required maxlength="100" placeholder="Example: outer forearm"></label><label>Approximate size <select name="size" required><option value="">Choose size</option><option>Small</option><option>Medium</option><option>Large</option><option>Unsure</option></select></label><label>Budget range <select name="budget" required><option value="">Choose a range</option><option>Under $300</option><option>$300–$600</option><option>$600–$1,000</option><option>$1,000+</option><option>Need guidance</option></select></label><label>Preferred timing <select name="timing" required><option value="">Choose timing</option><option>Within a month</option><option>1–3 months</option><option>Flexible</option></select></label></div><label>General concept <textarea name="concept" rows="5" maxlength="1000" required placeholder="Describe the idea and style; avoid private or health information"></textarea></label><label class="check"><input type="checkbox" name="ack" required> I understand this is a fictional demo; no message, reference image, appointment, deposit or payment is processed.</label><button class="button" type="submit">Preview consultation locally ↗</button><div id="result" role="status" aria-live="polite" tabindex="-1"></div></form></section>'''

for path,body in [('index.html',home),('artists.html',artists),('gallery.html',gallery),('experience.html',experience),('consultation.html',consult)]:
 (P/path).write_text(page(path,body),encoding='utf-8')
print('Built',len(pages),'tattoo studio pages')

